"""The first line of every generated file, which tells a file left behind from a hand-written one."""

from pathlib import Path, PurePosixPath

_TEXT = "Generated by datapatchbay from "
_COMMENTS = ("#", "--")
"""The comment markers of the files `dpb generate` commits: YAML and SQL."""


def generated_header(source: str | PurePosixPath, *, comment: str = "#") -> str:
    """Return the first line of a file generated from `source` (a path relative to the repo root), with its newline.

    Args:
        source: The file the generated file is derived from.
        comment: The comment marker of the file type, `#` for YAML and `--` for SQL.
    """
    return f"{comment} {_TEXT}{source}. Do not edit: `dpb generate` overwrites this file.\n"


def generated_from(path: Path) -> str | None:
    """Read the source file named in the first line of a generated file.

    Returns:
        The source path as written, or `None` when the file is unreadable, not text or has no generated header.
    """
    try:
        with path.open(encoding="utf-8") as stream:
            first = stream.readline()
    except (OSError, UnicodeDecodeError):
        return None
    for comment in _COMMENTS:
        prefix = f"{comment} {_TEXT}"
        if first.startswith(prefix):
            return first.removeprefix(prefix).split(". Do not edit", 1)[0].strip()
    return None
